mapper.select:
SELECT c.id, c.collision_no, NULL AS request_id, NULL AS third_order_no, c.phone_enc, c.user_name AS user_name_enc, c.channel_id, c.channel_code, ch.channel_name, ch.app_key AS channel_app_key, c.inst_id, COALESCE(c.inst_code, i.inst_code) AS inst_code, i.inst_name, c.product_id, COALESCE(ip.product_name, c.product_name_snapshot) AS product_name, CASE WHEN c.collision_status = 0 THEN 2 WHEN c.collision_status = 9 THEN 4 ELSE c.collision_status END AS push_status, NULL AS response_log, c.reject_reason AS error_msg, NULL AS cost_ms, c.created_at AS pushed_at, c.created_at, c.collision_status, c.reject_reason AS collision_reject_reason, c.settlement_price, c.downstream_price, c.product_coefficient_price, c.upstream_channel_price FROM collision_record c LEFT JOIN channel ch ON ch.id = c.channel_id LEFT JOIN institution i ON i.id = c.inst_id LEFT JOIN institution_product ip ON ip.id = c.product_id
AND c.collision_no = #{query.collisionNo}
AND c.phone_md5 = #{query.phoneMd5}
AND c.user_name_md5 = #{query.userNameMd5}
AND c.channel_code = #{query.channelCode}
AND c.collision_status = 0
AND c.collision_status = 9
AND c.created_at >= #{query.startTime}
AND c.created_at <= #{query.endTime}
ORDER BY c.created_at DESC, c.id DESC
